func processWithPool(jobs []string, workers int,
                     fn func(string) error) []error {
    sem := make(chan struct{}, workers)
    errs := make([]error, len(jobs))
    var wg sync.WaitGroup
    for i, job := range jobs {
        wg.Add(1)
        sem <- struct{}{}
        go func(idx int, j string) {
