function throttle<T extends (...args: unknown[]) => void>(
    fn: T, limitMs: number
): T {
    let lastCall = 0;
    return function (...args) {
        const now = Date.now();
        if (now - lastCall >= limitMs) {
            lastCall = now;
            fn(...args);
        }
    } as T;
}

