		if ( preg_match( '/^(-?\d+)\/(\d+)$/', $num, $m ) ) {
			$numerator = (int)$m[1];
			$denominator = (int)$m[2];
			$gcd = $this->gcd( abs( $numerator ), $denominator );
			if ( $gcd !== 0 ) {
