func (enc *Encoder) encodeObject(v MarshalerJSONObject) ([]byte, error) {
	enc.grow(512)
	enc.writeByte('{')
	if !v.IsNil() {
		v.MarshalJSONObject(enc)
	}
	if enc.hasKeys {
		enc.hasKeys = false
		enc.keys = nil
	}
	enc.writeByte('}')
	return enc.buf, enc.err
}

