	/**
	 * @param Config $config
	 * @param Config $mainConfig
	 * @param ILoadBalancer $lb
	 * @param EditionProvider $editionProvider
	 */
	public function __construct(
		Config $config, Config $mainConfig, ILoadBalancer $lb, EditionProvider $editionProvider
