		$starredMenteeIds = $this->getStarredMenteeIds( $user );
		$unstarredMenteeIds = array_diff( $menteeIds, $starredMenteeIds );

		$this->menteeCache->set( $key, $unstarredMenteeIds );
		return $unstarredMenteeIds;
	}

