private function assertThatHookIsExcutable( $hooks, array $arguments ) {
		if ( is_callable( $hooks ) ) {
			$hooks = [ $hooks ];
		}

		foreach ( $hooks as $hook ) {

			$this->assertIsBool(
				call_user_func_array( $hook, $arguments )
			);
		}
	}

